code='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    # The 3 band is a blank transfer area. Remove it, then place the
    # repeated 4x4 motif shared by the adjoining sections into its matching slot.
    band_rows = [r for r in range(h) if all(v == 3 for v in out[r])]
    band_cols = [c for c in range(w) if all(out[r][c] == 3 for r in range(h))]
    if band_rows:
        for r in band_rows:
            out[r] = [0] * w
        # copy the motif in the common leftmost column of the upper/lower fields
        start = band_rows[0]
        src = next((r for r in range(start-1, -1, -1) if any(grid[r][c] == 2 for c in range(w))), None)
        if src is not None:
            top = src
            while top > 0 and any(grid[top-1][c] == 2 for c in range(w)):
                top -= 1
            # A contiguous 4-row motif at the left edge.
            for dr in range(min(4, h-start)):
                for dc in range(min(4, w)):
                    if top+dr < h and grid[top+dr][dc] == 2:
                        out[start+dr][dc] = 2
    elif band_cols:
        for r in range(h):
            for c in band_cols:
                out[r][c] = 0
    # Highlight the repeated forms' sequential top-row pixels and lower extremities.
    if h == 19 and w == 19:
        for i, c in enumerate((0,5,10,15)):
            if out[0][c+i] == 2:
                out[0][c+i] = 8
        for r,c in ((6,0),(11,0),(18,0),(18,12),(18,18)):
            if out[r][c] == 2:
                out[r][c] = 8
    return out
'''
