code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    band = [r for r in range(h) if all(v == 3 for v in grid[r])]
    if not band:
        return out
    start = band[0]
    for r in band:
        out[r] = [0] * w
    # The repeated 4x4 motif's row pixels encode which tile columns are occupied.
    motif = [row[:4] for row in grid[:4]]
    pitch = 5
    for tile_row in range(4):
        if start + tile_row >= h:
            continue
        for tile_col in range(4):
            if motif[tile_row][tile_col] != 2:
                continue
            c0 = pitch * tile_col
            r0 = pitch * tile_row
            if tile_row == start // pitch:
                r0 = start
            for dr in range(4):
                for dc in range(4):
                    if r0 + dr < h and c0 + dc < w and motif[dr][dc] == 2:
                        out[r0 + dr][c0 + dc] = 2
            mark_r = r0 + tile_row
            mark_c = c0 + tile_col
            if mark_r < h and mark_c < w and out[mark_r][mark_c] == 2:
                out[mark_r][mark_c] = 8
    return out
'''
